  .container{max-width:1200px;margin:20px auto;padding:0 20px;}
  .detail{display:flex;gap:20px;flex-wrap:wrap;}
  .detail img{width:400px;height:400px;object-fit:cover;border:1px solid #e0e0e0;}
  .info{flex:1;}
  .info h2{margin-top:0;font-size:28px;color:#333;}
  .info p{font-size:16px;color:#555;margin-top:10px;}
  .price{font-size:24px;color:#e91e63;margin:15px 0;}
  .size-select{margin:10px 0;}
  .size-select label{margin-right:10px;}
  .size-select select{padding:5px;}
  .qty-input{margin:10px 0;}
  .qty-input label{margin-right:10px;}
  .qty-input input{width:60px;padding:5px;}
  .btn{display:inline-block;background:#007aff;color:#fff;padding:10px 20px;border-radius:4px;text-decoration:none;font-size:16px;}
  .btn:hover{background:#005bb5;}
  footer{background:#fff;border-top:1px solid #e0e0e0;text-align:center;padding:20px 0;color:#777;font-size:14px;}
  @media(max-width:768px){
    .detail{flex-direction:column;}
    .detail img{width:100%;}
  }
</style>
</head>
<body>
<header>
  <div class="logo"><a href="index.html" style="font-size:20px;font-weight:bold;color:#333;text-decoration:none;">可衣</a></div>
  <nav>
    <a href="index.html">首页</a>
    <a href="products.html">产品</a>
    <a href="cart.html">购物车</a>
  </nav>
</header>
<section class="container">
  <div id="product" class="detail">
    <img id="product-image" src="" alt="">
    <div class="info">
      <h2 id="product-name"></h2>
      <p id="product-desc"></p>
      <div class="price" id="product-price"></div>
      <div class="size-select">
        <label>尺码：</label>
        <select id="size-select"></select>
      </div>
      <div class="qty-input">
        <label>数量：</label>
        <input type="number" id="qty-input" value="1" min="1">
      </div>
      <button id="add-to-cart" class="btn">加入购物车</button>
    </div>
  </div>
</section>
<footer>© 2024 可衣 上海 | 关注我们：微信、微博</footer>
<script>
  const products = [
    {
      id: '1',
      name: '简约连衣裙',
      desc: '一款适合日常与商务场合的简约连衣裙，采用柔软面料，修身剪裁，展现优雅气质。',
      price: 299,
      sizes: ['S', 'M', 'L', 'XL'],
      img: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8Xw8AAoMBgqXx1x8AAAAASUVORK5CYII='
    },
    {
      id: '2',
      name: '高腰牛仔裤',
      desc: '经典牛仔，修身显腿长，适合各种休闲场合。',
      price: 199,
      sizes: ['S', 'M', 'L', 'XL'],
      img: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8Xw8AAoMBgqXx1x8AAAAASUVORK5CYII='
    },
    {
      id: '3',
      name: '商务衬衫',
      desc: '专业商务场合的必备单品，面料柔软透气，剪裁合身。',
      price: 149,
      sizes: ['S', 'M', 'L', 'XL'],
      img: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8Xw8AAoMBgqXx1x8AAAAASUVORK5CYII='
    }
  ];

  function getQueryParam(name) {
    const urlParams = new URLSearchParams(window.location.search);
    return urlParams.get(name);
  }

  function loadProduct() {
    const id = getQueryParam('id');
    const prod = products.find(p => p.id === id);
    if (!prod) return;
    document.getElementById('product-image').src = prod.img;
    document.getElementById('product-image').alt = prod.name;
    document.getElementById('product-name').textContent = prod.name;
    document.getElementById('product-desc').textContent = prod.desc;
    document.getElementById('product-price').textContent = '¥' + prod.price;
    const sizeSelect = document.getElementById('size-select');
    prod.sizes.forEach(s => {
      const option = document.createElement('option');
      option.value = s;
      option.textContent = s;
      sizeSelect.appendChild(option);
    });
  }

  function addToCart() {
    const id = getQueryParam('id');
    const size = document.getElementById('size-select').value;
    const qty = parseInt(document.getElementById('qty-input').value, 10) || 1;
    const cart = JSON.parse(localStorage.getItem('cart')) || [];
    const existing = cart.find(item => item.id === id && item.size === size);
    if (existing) {
      existing.qty += qty;
    } else {
      cart.push({ id, size, qty });
    }
    localStorage.setItem('cart', JSON.stringify(cart));
    alert('已加入购物车');
  }

  document.getElementById('add-to-cart').addEventListener('click', addToCart);
  window.addEventListener('load', loadProduct);
</script>
</body>
</html>

